package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_reduce_TriageGen2Test {

    @Test
    public void testReduce_AlreadyReduced() {
        // Case where gcd is 1, should return 'this'
        Fraction fraction = Fraction.getFraction(3, 7);
        Fraction reduced = fraction.reduce();

        assertSame("Should return the same instance if gcd is 1", fraction, reduced);
        assertEquals(3, reduced.getNumerator());
        assertEquals(7, reduced.getDenominator());
    }

    @Test
    public void testReduce_NeedsReduction() {
        // Case where gcd > 1, should return a new reduced fraction
        Fraction fraction = Fraction.getFraction(4, 8);
        Fraction reduced = fraction.reduce();

        assertNotSame("Should return a new instance when reduction occurs", fraction, reduced);
        assertEquals(1, reduced.getNumerator());
        assertEquals(2, reduced.getDenominator());
    }

    @Test
    public void testReduce_LargeReduction() {
        // Case with larger numbers
        Fraction fraction = Fraction.getFraction(100, 250);
        Fraction reduced = fraction.reduce();

        assertEquals(2, reduced.getNumerator());
        assertEquals(5, reduced.getDenominator());
    }

    @Test
    public void testReduce_NegativeNumerator() {
        // Testing Math.abs logic in gcd calculation
        // gcd(abs(-4), 8) = gcd(4, 8) = 4
        Fraction fraction = Fraction.getFraction(-4, 8);
        Fraction reduced = fraction.reduce();

        assertEquals(-1, reduced.getNumerator());
        assertEquals(2, reduced.getDenominator());
    }

    @Test
    public void testReduce_UnitNumerator() {
        // gcd(1, 5) = 1
        Fraction fraction = Fraction.getFraction(1, 5);
        Fraction reduced = fraction.reduce();

        assertSame(fraction, reduced);
    }

    @Test
    public void testReduce_LargeCommonDivisor() {
        // gcd(12, 12) = 12
        Fraction fraction = Fraction.getFraction(12, 12);
        Fraction reduced = fraction.reduce();

        assertEquals(1, reduced.getNumerator());
        assertEquals(1, reduced.getDenominator());
    }
}
